local ports = require("src.foundation.ports.runtime_ports")
describe("hook errors", function()
  describe("bad setup", function()
    before_each(function() ports.reset_for_tests(); error("setup exploded") end)
    it("must not execute its body", function() error("unexpected body") end)
  end)
  describe("bad teardown", function()
    after_each(function() ports.reset_for_tests(); error("teardown exploded") end)
    it("passes before teardown explodes", function() assert.is_true(ports.is_configured()) end)
  end)
  it("victim still sees shared ports", function() assert.is_true(ports.is_configured()) end)
end)
